H.background();
const w = H.W, h = H.H;
const T = Math.max(50, P.T), N = Math.max(1, Math.round(P.N)), m = Math.max(1, P.m);
const k = 1.38e-23;                 // Boltzmann constant
const mkg = m * 1.66e-27;           // molar mass (u) -> kg per molecule
const vrms = Math.sqrt(3 * k * T / mkg);   // root-mean-square speed (m/s)
const KEavg = 1.5 * k * T;          // average translational KE per molecule (J)
// gas box
const bx = 60, by = 80, bw = w - 120, bh = h - 150;
H.rect(bx, by, bw, bh, { stroke: H.colors.axis, width: 2 });
const speedPx = H.clamp(vrms / 800, 0.5, 4.0);   // on-screen speed proportional to v_rms
const rnd = (s) => { const x = Math.sin(s) * 43758.5453; return x - Math.floor(x); };
const tri = (val, range) => { const p = ((val % (2 * range)) + 2 * range) % (2 * range); return p < range ? p : 2 * range - p; };
for (let i = 0; i < N; i++) {
  const ang = rnd(i + 1) * H.TAU;
  const sp = speedPx * (0.7 + 0.6 * rnd(i + 7));
  const x0 = rnd(i + 13) * (bw - 30), y0 = rnd(i + 19) * (bh - 30);
  const px = bx + 15 + tri(x0 + Math.cos(ang) * sp * t * 50, bw - 30);
  const py = by + 15 + tri(y0 + Math.sin(ang) * sp * t * 50, bh - 30);
  if (i === 0) {
    H.circle(px, py, 6, { fill: H.colors.warn });
    H.arrow(px, py, px + Math.cos(ang) * 26, py + Math.sin(ang) * 26, { color: H.colors.warn, width: 2 });
  } else {
    H.circle(px, py, 4, { fill: H.color(i % 8) });
  }
}
H.text("Kinetic theory: v_rms = sqrt(3 k T / m)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("T = " + T.toFixed(0) + " K   m = " + m.toFixed(0) + " u   N = " + N + "   v_rms = " + vrms.toFixed(0) + " m/s", 24, 54, { color: H.colors.sub, size: 13 });
